    int i;
    int pos;

    if (!dctx->frame_start_found) {
        for (i = 0; i < buf_size; i++) {
            if (buf[i] == 0x00 && buf[i + 1] == 0x00 && buf[i + 2] == 0x01) {
                dctx->frame_start = 1;
                dctx->frame_start_found = 1;
                dctx->frame_start_index = i + 3;
                return END_NOT_FOUND;
            }
        }
        return END_NOT_FOUND;
    } else {
        pos = dctx->frame_start_index;
        if (pos + 3 <= buf_size) {
            dctx->width = (buf[pos] << 8) | buf[pos + 1];
            dctx->height = (buf[pos + 2] << 8) | buf[pos + 3];
            dctx->interlaced = (buf[pos + 4] & 0x80) != 0;
            dctx->remaining_bytes = ((dctx->width * dctx->height) / 2) * 3;
