            return dctx->remaining_bytes;
        } else {
            return END_NOT_FOUND;
        }
    }
}

int find_dnxhd_frame_end(DNXHDParserContext *dctx, const uint8_t *buf, int buf_size) {
    int i;
    const uint8_t *buf_end = buf + buf_size;

    if (!dctx->frame_start_found) {
        for (i = 0; i < buf_size - 2; i++) {
            if (buf[i] == 0x00 && buf[i + 1] == 0x13) {
                dctx->frame_start_found = 1;
                dctx->buf_ptr = buf + i + 2;
                dctx->buf_end = buf_end;
                dctx->frame_size = 0;
                break;
            }
        }
    }

    if (dctx->frame_start_found) {
        if (!dctx->frame_size) {
            if (dctx->buf_ptr + 4 > buf_end)
                return END_NOT_FOUND;

            dctx->frame_size = ((dctx->buf_ptr[0] & 0x0F) << 20) |
                               (dctx->buf_ptr[1] << 12) |
                               (dctx->buf_ptr[2] << 4) |
                               ((dctx->buf_ptr[3] >> 4) & 0x0F);
            dctx->frame_size *= 2;

            dctx->interlaced = (dctx->buf_ptr[0] & 0x80) != 0;
            dctx->buf_ptr += 4;
        }

        if (dctx->buf_ptr + dctx->frame_size <= buf_end) {
            dctx->frame_start_found = 0;
            return dctx->frame_size;
        }
    }

    return END_NOT_FOUND;
}

int find_dnxhd_frame_end(DNXHDParserContext *dctx, const uint8_t *buf, int buf_size) {
    int i;
    int index = dctx->index;
    int pos = dctx->frame_start;

    for (i = 0; i < buf_size; i++) {
        if (buf[i] == 0x1F) {
            if (i + 1 < buf_size && buf[i + 1] == 0x40) {
                // Header prefix found
                if (i + 4 < buf_size) {
                    // Read more data to determine frame info
                    int width = ((buf[i + 2] & 0x3F) << 4) | ((buf[i + 3] >> 4) & 0x0F);
                    int height = (((buf[i + 3] & 0x0F) << 8) | (buf[i + 4] & 0xFF));
                    dctx->frame_width = width;
                    dctx->frame_height = height;

                    // Calculate the size of the frame based on resolution
                    int frame_size = dnxhd_get_frame_size(width, height);

                    if (frame_size <= 0) {
                        continue;
                    }

                    dctx->frame_size = frame_size;
                    dctx->frame_start = i;

                    // Interlaced frame handling
                    if (buf[i + 2] & 0x80) {
                        dctx->interlaced = 1;
                        frame_size *= 2;
                    }

                    if (i + frame_size <= i + buf_size) {
                        // End of frame is within the buffer
                        dctx->index = i + frame_size;
                        return dctx->index - (pos + frame_size);
                    } else {
                        // End of frame is not yet in the buffer
                        dctx->index = i;
                        return END_NOT_FOUND;
                    }
                }
            }
        }
    }

    // End of frame not found in buffer
    dctx->index = index;
    return END_NOT_FOUND;
}

int find_dnxhd_frame_end(DNXHDParserContext *dctx, const uint8_t *buf, int buf_size) {
    int i;

    if (!dctx->frame_start_found) {
        // Search for the header prefix
        for (i = 0; i < buf_size - 3; i++) {
            if (buf[i] == 0x00 && buf[i+1] == 0x00 && buf[i+2] == 0x01) {
                dctx->frame_start_found = 1;
                dctx->frame_offset = i + 3;
                // Read additional data to determine frame dimensions and bytes remaining
                dctx->frame_bytes_remaining = AV_RB24(buf + i + 3);
                if (dctx->frame_bytes_remaining > 0) {
                    return dctx->frame_bytes_remaining;
                }
            }
        }
    } else {
        // Track remaining bytes
        dctx->frame_bytes_remaining -= buf_size;

        if (dctx->frame_bytes_remaining <= 0) {
            // End of frame reached
            if (dctx->frame_interlaced) {
                dctx->field++ % 2;
            }
            dctx->frame_start_found = 0;
            return END_NOT_FOUND;
        }
    }

    return dctx->frame_bytes_remaining;
}

int find_dnxhd_frame_end(DNXHDParserContext *dctx, const uint8_t *buf, int buf_size) {
    int i;

    if (!dctx->frame_start_found) {
        for (i = 0; i < buf_size; i++) {
            if (buf[i] == 0x00 && buf[i + 1] == 0x14) {
                dctx->frame_start_found = 1;
                dctx->current_idx = i + 2;
                return buf_size - i - 2;
            }
        }
        return END_NOT_FOUND;
    } else {
        int remaining = dctx->remaining;
        int start_idx = dctx->current_idx;
        int end_idx = start_idx + remaining;

        if (start_idx >= buf_size)
            return END_NOT_FOUND;

        if (end_idx > buf_size)
            end_idx = buf_size;

        for (i = start_idx; i < end_idx; i++) {
            if (buf[i] == 0x00 && buf[i + 1] == 0x14) {
                dctx->frame_start_found = 0;
                dctx->current_idx = i + 2;
                dctx->remaining = 0;
                return i - start_idx;
            }
        }

        dctx->remaining -= i - start_idx;
        dctx->current_idx = i;
        return END_NOT_FOUND;
    }
}
